def parse_port(raw):
    port = int(raw)
    if not (1 <= port <= 65535):
        raise ValueError("Port out of range")
    return port

for text in ["8090", "bad", "99999"]:
    try:
        print("Valid:", parse_port(text))
    except ValueError as err:
        print("Rejected:", text, err)

